/**
 * Contract between the agent and its clients (the Tomari overlay, mirrored in
 * Sources/TomariCore/Protocol.swift, and claude-panel's Pi panel), over a WebSocket at
 * ws://127.0.0.1:PANEL_PORT/ws?token=<pairing token>, or the Mac's LAN address with `--lan`.
 * The agent sends a snapshot on connect, then one message per change. The Pi panel shows sessions
 * that are `live || pinned`; Tomari shows pinned ones and those working or waiting on the user.
 */

export const PANEL_PORT = 7778;

/** Pairing file the panel loads from ./config.json; generated by the agent. */
export interface PanelConfig {
  /** Ways to reach the agent, tried in order until one connects: ws://<address>:PANEL_PORT/ws */
  agentUrls: string[];
  token: string;
}

export const SESSION_STATES = [
  "idle", // started, no prompt yet
  "working",
  "needs_permission",
  "needs_input", // a question, a plan to review, or otherwise waiting on the user
  "compacting",
  "done", // finished its turn: the user's move
  "error",
  "ended", // process gone
] as const;

export type SessionState = (typeof SESSION_STATES)[number];

export interface SessionIcon {
  /** Sprite sheet id. */
  character: string;
  /** "#rrggbb" */
  color: string;
}

export const DEFAULT_ICON: SessionIcon = { character: "default", color: "#d97757" };

/** What Claude Code's statusline reports for one session. Every field is null until a reading has it. */
export interface SessionUsage {
  /** Session cost so far, USD; the client's estimate. */
  costUsd: number | null;
  /** Share of the context window in use, 0-100. */
  contextPct: number | null;
  inputTokens: number | null;
  outputTokens: number | null;
}

/** One rate-limit window of the account (Claude Pro/Max only). */
export interface LimitWindow {
  /** 0-100 */
  usedPct: number;
  /** Epoch ms when the window resets. */
  resetsAt: number;
}

/** Account-wide limits, shared by every session. A window is null while Claude Code doesn't report it. */
export interface AccountLimits {
  fiveHour: LimitWindow | null;
  sevenDay: LimitWindow | null;
  /** Epoch ms of the reading. */
  updatedAt: number;
}

/** What every session together has cost on one local calendar day. */
export interface DailySpend {
  /** Local date, YYYY-MM-DD. */
  day: string;
  usd: number;
}

export interface PanelSession {
  id: string;
  name: string;
  cwd: string;
  state: SessionState;
  /** Short detail for the tile, e.g. "Bash: npm test". */
  activity: string | null;
  /** The Claude process is running. */
  live: boolean;
  /** Epoch ms of the last state change. */
  stateSince: number;
  pinned: boolean;
  /** Order among pinned sessions; null when not pinned. */
  position: number | null;
  icon: SessionIcon;
  /** Optional: absent until the statusline has reported, and for clients that predate it. */
  usage?: SessionUsage;
}

/** A desktop-app session the panel can pin, running or not. */
export interface LibraryEntry {
  id: string;
  name: string;
  cwd: string;
  /** Epoch ms of its last activity. */
  lastActivityAt: number;
  pinned: boolean;
}

export type ServerMessage =
  | { type: "snapshot"; sessions: PanelSession[]; focusedId: string | null }
  | { type: "session"; session: PanelSession }
  | { type: "removed"; id: string }
  | { type: "focus"; id: string | null } // the session in front in the desktop app; null when none
  | { type: "library"; sessions: LibraryEntry[] } // reply to a library request, most recent first
  | { type: "limits"; limits: AccountLimits } // sent after the snapshot once known, then on every change
  | { type: "spend"; spend: DailySpend } // sent after the limits once above zero, then on every change
  | { type: "error"; message: string };

/** `pin` and `icon` also accept a desktop session that isn't running: the agent starts tracking it. */
export type ClientMessage =
  | { type: "open"; id: string }
  | { type: "pin"; id: string; pinned: boolean }
  | { type: "icon"; id: string; icon: SessionIcon } // pins the session if it isn't yet
  | { type: "library" };
